// Remove meta http-equiv="refresh".
RefPtr<mozilla::dom::ContentList> metas =
    document->GetElementsByTagName(u"meta"_ns);
uint32_t length = metas->Length();
for (uint32_t i = length; i > 0; i--) {
  RefPtr<nsGenericHTMLElement> node =
      nsGenericHTMLElement::FromNodeOrNull(metas->Item(i - 1));
  nsAutoString header;
  node->GetAttr(kNameSpaceID_None, nsGkAtoms::httpEquiv, header);
  nsContentUtils::ASCIIToLower(header);
  if (nsGkAtoms::refresh->Equals(header)) {
    node->Remove();
  }
}

if (mozilla::StaticPrefs::mail_html_sanitize_drop_conditional_css()) {
  nsTreeSanitizer::RemoveConditionalCSSFromSubtree(document);
}
